const intervalMap={};const UPDATE_INTERVAL_MS=5e3;const canban_statuses=document.querySelectorAll("[data-status][data-level]");executeFunc((function scheduleAutoSubmitOrderDeliveryFilterForm(){if(typeof formDebounce!=="function"){return false}const form=document.forms.order_delivery_filter_form;if(typeof form==="undefined"){return false}const debouncedSubmit=formDebounce((()=>{const data=new FormData(form);for(const status of canban_statuses){const draggableElements=status.querySelectorAll(".draggable");draggableElements.forEach((element=>{element.style.transition="opacity 0.5s ease, transform 0.5s ease";requestAnimationFrame((()=>{element.style.opacity="0";element.style.transform="scale(0.9)"}));element.addEventListener("transitionend",(()=>{element.remove()}))}));updateStatus(status,data)}}),1e3);const inputFields=form.querySelectorAll("input, select, textarea");inputFields.forEach((field=>{if(field.tagName==="INPUT"){field.addEventListener("input",debouncedSubmit);field.addEventListener("keyup",debouncedSubmit)}if(field.tagName==="SELECT"){field.addEventListener("change",debouncedSubmit)}field.addEventListener("focus",(event=>{if(idFormDebounce){clearTimeout(idFormDebounce)}if(lastFormDebounce){clearTimeout(idFormDebounce)}}));form.querySelectorAll(".clear-btn").forEach((btn=>{btn.addEventListener("click",(e=>{e.preventDefault();const fieldId=btn.dataset.clear;const input=form.querySelector(`#${fieldId}`);if(input){input.value="";if(idFormDebounce){clearTimeout(idFormDebounce)}if(lastFormDebounce){clearTimeout(idFormDebounce)}debouncedSubmit()}}))}))}));return true}));async function updateStatus(status,form_data){try{const response=await fetch("/admin/orders_status/"+status.dataset.status,{method:"POST",cache:"no-cache",credentials:"same-origin",headers:{"X-Requested-With":"XMLHttpRequest"},redirect:"follow",referrerPolicy:"no-referrer",body:form_data});if(!response.ok){throw new Error(`HTTP error! status: ${response.status}`)}const data=await response.text();if(data){status.innerHTML=data;let lazy=document.createElement("script");lazy.src="/assets/"+$version+"/js/lazyload.min.js?v="+Date.now();document.head.appendChild(lazy);executeFunc((()=>{document.querySelectorAll(".offcanvas-link").forEach((function(item){item.addEventListener("click",(function(){offcanvasLink(item)}));item.classList.remove("offcanvas-link")}));var tooltipTriggerList=[].slice.call(document.querySelectorAll('[data-bs-toggle="tooltip"]'));tooltipTriggerList.map((function(tooltipTriggerEl){const tooltipInstance=new bootstrap.Tooltip(tooltipTriggerEl);tooltipTriggerEl.addEventListener("click",(event=>{tooltipInstance.hide()}));tooltipTriggerEl.removeAttribute("data-bs-toggle");return tooltipInstance}));return true}),300)}}catch(error){console.error(`[Canban] Ошибка обновления статуса ${status.dataset.status}:`,error)}}function startStatusUpdate(status,intervalMs){const oldInterval=intervalMap[status.dataset.status];if(oldInterval){clearInterval(oldInterval)}async function scheduleUpdate(){await updateStatus(status,null);const timeoutId=setTimeout(scheduleUpdate,intervalMs);intervalMap[status.dataset.status]={timeoutId:timeoutId,promise:Promise.resolve()}}const startDelay=Math.floor(Math.random()*intervalMs);setTimeout(scheduleUpdate,startDelay)}function stopStatusUpdate(statusKey){if(intervalMap[statusKey]){clearTimeout(intervalMap[statusKey].timeoutId);delete intervalMap[statusKey]}}for(const status of canban_statuses){updateStatus(status,null)}for(const status of canban_statuses){startStatusUpdate(status,UPDATE_INTERVAL_MS)}window.addEventListener("pagehide",(function(){Object.keys(intervalMap).forEach((key=>stopStatusUpdate(key)))}));